INSERT INTO `reason_resign` VALUES
(1,'{\"vi\": \"Có cơ hội việc làm tốt hơn(Lập nghiệp)\", \"en\": \"There is a better job\", \"cn\": \"另有好的工作機會（職業生涯）\"}'),
(2,'{\"vi\": \"Lý do sức khỏe(Dưỡng bệnh)\", \"en\": \"Health is not sufficient to continue working\", \"cn\": \"身體原因（生病休養）\"}'),
(3,'{\"vi\": \"Lý do gia đình(Kết hôn/Chăm con/Chăm sóc người thân/Về quê/Chuyển nơi ở…)\", \"en\":  \"Family reasons (Marriage/Childcare/Care for relatives/Return to hometown/Move residence…)\", \"cn\": \"家庭因素（結婚/照顧小孩/照顧家人/返鄉/搬家）\"}'),
(4,'{\"vi\": \"Không phù hợp sở thích cá nhân\", \"en\":\"not suitable for personal taste\", \"cn\": \"與個人興趣不符\"}'),
(5,'{\"vi\": \"Không thể đảm nhận CV hiện tại(Năng lực)\", \"en\": \"Unable to perform current job (Capacity)\", \"cn\": \"無法勝任目前的工作（能力）\"}'),
(6,'{\"vi\": \"Không thể hòa nhập với Cty(Văn hóa)\", \"en\": \"Can\'t fit in with the company (Culture)\", \"cn\": \"無法融入企業（文化不適應）\"}'),
(7,'{\"vi\": \"Không cơ hội phát triển(Thăng tiến cá nhân)\", \"en\": \"No development prospects (personal growth and promotion)\", \"cn\": \"無發展前景（個人成長與升遷）\"}'),
(8,'{\"vi\": \"Chế độ phúc lợi chưa tốt\", \"en\": \"Welfare regime is not good\", \"cn\": \"福利制度欠佳\"}'),
(9,'{\"vi\": \"Đánh giá xếp loại không khách quan\", \"en\": \"Rating is not objective\", \"cn\": \"考核制度欠缺客觀\"}'),
(10,'{\"vi\": \"Trong TG thử việc không đạt YC\", \"en\": \"Failed probation period\", \"cn\": \"試用期內不合格\"}'),
(11,'{\"vi\": \"Công ty chấm dứt HĐLĐ\", \"en\": \"Company terminates labor contract\", \"cn\": \"公司終止僱用\"}'),
(12,'{\"vi\": \"Nghỉ hưu\", \"en\": \"Retirement\", \"cn\": \"退休\"}'),
(13,'{\"vi\": \"Nghỉ không phép 5 ngày\", \"en\": \"Absenteeism for five days (Termination of Contract)\", \"cn\": \"曠職5天\"}'),
(14,'{\"vi\": \"Hết hạn hợp đồng\", \"en\": \"Contract Expiry\", \"cn\": \"合約到期\"}'),
(15,'{\"vi\": \"Đi học\", \"en\": \"Study\", \"cn\": \"進修就學\"}'),
(16,'{\"vi\": \"Đi nghĩa vụ quân sự\", \"en\": \"Go to military service\", \"cn\": \"服兵役\"}'),
(17,'{\"vi\": \"Sa thải - Nghỉ không phép 5 ngày\", \"en\": \"Dismissed - Absenteeism for five days\", \"cn\": \"開除\"}'),
(18,'{\"vi\": \"Lý do khác\", \"en\": \"Other reasons\", \"cn\": \"其他原因\"}'),
(19,'{\"vi\": \"Sa thải - Lý do khác\", \"en\":\"Dismissed - Other reasons\", \"cn\": \"開除-其他原因\"}');
